// Writes src/lowercase_changed.rs from js_lowercase.json: the code points Node's toLowerCase() changes.
// Run: node js_lowercase_table.mjs   (in testdata/)
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const golden = JSON.parse(readFileSync(new URL('./js_lowercase.json', import.meta.url), 'utf8'));
const cps = golden.rows.map((row) => row[0]);
const lines = [];
for (let i = 0; i < cps.length; i += 12) {
  lines.push(`    ${cps.slice(i, i + 12).map((cp) => `0x${cp.toString(16).toUpperCase()}`).join(', ')},`);
}
const text = `// Generated by testdata/js_lowercase_table.mjs from testdata/js_lowercase.json (Node's toLowerCase()); do not edit.
// Every code point Node's \`String.prototype.toLowerCase()\` changes, ascending.
pub(super) const CHANGED: [u32; ${cps.length}] = [
${lines.join('\n')}
];
`;
writeFileSync(fileURLToPath(new URL('../src/lowercase_changed.rs', import.meta.url)), text);
